import { readFileSync } from "node:fs";

import { expect, test, sample, uniqueName } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test("upload a document", { tag: "@DOC-01" }, async ({ apiAs }) => {
    // Arrange: a draft vendor owned by the member's tenant
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Doc Vendor"),
        category: "services",
        contact_email: `ops-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
      },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();
    expect(vendor.status).toBe("draft");

    // Act: upload the insurance certificate sample
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: "insurance_certificate.txt",
          mimeType: "text/plain",
          buffer: readFileSync(sample("insurance_certificate.txt")),
        },
      },
    });

    // Assert: response status and body
    expect(res.status(), await res.text()).toBe(201);
    const document = await res.json();
    expect(document.status, await res.text()).toBe("processing");
    expect(document.vendor_id).toBe(vendor.id);
    expect(document.kind).toBe("insurance_certificate");

    // Assert: audit event recorded (written by the upload, polled in case of async writes)
    await expect
      .poll(
        async () => {
          const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
          expect(audit.status(), await audit.text()).toBe(200);
          const body = (await audit.json()) as { items: { action: string }[] };
          return body.items.map((item) => item.action);
        },
        { timeout: 15_000 },
      )
      .toContain("document.uploaded");
  });
});
